ga0a(){return"\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0631\u0636"},
ga09(){return"\u0646\u0634\u0637"},
gZF(){return"\u0627\u0644\u0627\u0633\u0645"},
gZE(){return"\u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u0643\u0648\u0651\u0646\u0629"},
gZG(){return"\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
gZD(){return"\u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629"},
