gNW(){return"\u0695\u06ce\u06a9\u0646\u06d5\u062e\u0631\u0627\u0648\u06d5"},
gNP(){return"\u0628\u06d5\u0645 \u0632\u0648\u0648\u0627\u0646\u06d5"},
gNQ(){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646"},
NS(a){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06cc "+a},
gNU(){return"\u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0644\u06d5 \u0695\u06ce\u06af\u06d5\u06cc \u0626\u06d5\u0645 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5\u0648\u06d5"},
