gOJ(){return"\u0646\u0627\u0648\u06cc \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u06d5\u0631"},
gOH(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gOI(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06ce\u0631\u0645\u06cc\u0646\u0627\u06b5"},
gNK(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u06a9\u0695\u06cc\u0627\u0631"},
gNL(){return"\u06a9\u06c6\u062f\u06cc \u0646\u0647\u06ce\u0646\u06cc \u06a9\u0695\u06cc\u0627\u0631"},
gOd(){return"\u06a9\u0644\u06cc\u0644\u06cc API"},
gOe(){return"\u06a9\u0644\u06cc\u0644\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gOt(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce\u06a9\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06cc \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646 \u0628\u06c6 \u0648\u06b5\u0627\u062a\u06d5\u06a9\u06d5\u062a \u0628\u06d5\u0631\u062f\u06d5\u0633\u062a \u0646\u06cc\u06cc\u06d5. \u0626\u06d5\u06af\u06d5\u0631 \u062f\u06d5\u062a\u06d5\u0648\u06ce\u062a \u06cc\u06d5\u06a9\u06ce\u06a9 \u0632\u06cc\u0627\u062f \u0628\u06a9\u0631\u06ce\u062a \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u0645\u0627\u0646 \u067e\u06ce\u0648\u06d5 \u0628\u06a9\u06d5."},
gNO(){return"\u0628\u06d5\u0633\u062a\u06d5\u0631\u06cc \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gNN(){return"\u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646\u06cc \u062a\u0627\u0642\u06cc\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5\u0648\u06d5. \u0626\u06d5\u0645 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5 \u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646\u06cc \u0628\u06d5\u0631\u0647\u06d5\u0645\u0647\u06ce\u0646\u0627\u0646\u06cc \u062e\u06c6\u06cc \u0628\u06d5 \u06af\u0634\u062a\u06cc \u0628\u06b5\u0627\u0648 \u0646\u0627\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u2014 \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5 \u062f\u0648\u0627\u06cc \u067e\u06d5\u0633\u0646\u062f\u06a9\u0631\u062f\u0646\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0644\u06ce\u06cc \u0648\u06d5\u0631\u0628\u06af\u0631\u06d5."},
gOy(){return"\u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06d5\u06a9\u0627\u0646\u0645"},
