gNx(){return"\u0647\u06cc\u0686 \u0646\u06cc\u0633\u0628\u06d5\u06cc\u06d5\u06a9 \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0646\u06cc\u06cc\u06d5"},
