gafB(){return"\u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce"},
gafu(){return"\u0628\u06c6\u062a\u06d5\u06a9\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u06cc\u06ce \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5 \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u0646 \u062a\u06d5: \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u06af\u06d5\u0644 \u0648\u06ce\u0646\u06d5 \u0648 \u0641\u0627\u06cc\u0644\u06ce\u0646 \u0633\u06a9\u0627\u0646\u06ce \u0698 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u0641\u0631\u06ce\u06a9\u06d5\u0646\u060c \u06a9\u06d5\u06cc\u0633 \u062f\u06af\u06d5\u0647\u0646\u06d5 \u062f\u0627\u062e\u0648\u0627\u0632\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u060c \u0648 \u0644 \u0647\u06d5\u0631 \u0642\u0648\u0646\u0627\u063a\u06d5\u06a9\u06ce \u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u0628\u06c6 \u0648\u0627\u0646 \u062f\u0647\u06ce\u062a. \u06a9\u0627\u0631\u067e\u06ce\u06a9\u0631\u0646\u0627 \u0648\u06cc \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631\u06d5."},
