gZB(){return"\u0628\u06ce \u067e\u06c6\u0644"},
gGO(){return"\u0628\u06ce \u067e\u06c6\u0644"},
ZU(a){return"\u062a\u0648 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06cc \u062f\u06ce \u067e\u06c6\u0644\u0627 \xab"+a+"\xbb \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
